const incoming = $input.first().json;
const campaign = incoming.body ?? incoming;
if (!campaign || typeof campaign !== 'object' || Array.isArray(campaign)) {
  throw new Error('Webhook body must contain one campaign JSON object');
}
return [{ json: campaign }];

// n8n Code node: Run Once for All Items
const campaign = $input.first().json;
const unique = (values) => {
  const seen = new Set();
  return (values ?? []).filter((value) => {
    if (typeof value !== 'string' || value.trim() === '') return false;
    const key = value.trim().toLocaleLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const locations = unique([...(campaign.governorates ?? []), ...(campaign.cities ?? [])]);
const sectors = unique(campaign.sectors);
const preferredLanguages = unique(campaign.language_preferences ?? ['fr']);
const maximumQueries = campaign.limits?.maximum_queries ?? 40;
const maximumPerSource = campaign.limits?.maximum_queries_per_source ?? maximumQueries;

if (!Number.isInteger(maximumQueries) || maximumQueries < 1) {
  throw new Error('limits.maximum_queries must be a whole number of at least 1');
}
if (!Number.isInteger(maximumPerSource) || maximumPerSource < 1) {
  throw new Error('limits.maximum_queries_per_source must be a whole number of at least 1');
}

const sources = (campaign.enabled_sources ?? []).filter((source) => {
  if (source.source_type === 'registry') return false;
  return ['keyword', 'sector', 'location'].some((capability) =>
    (source.capabilities ?? []).includes(capability),
  );
});

if (!campaign.campaign_id || sectors.length === 0 || locations.length === 0 || sources.length === 0) {
  throw new Error('Campaign requires campaign_id, sectors, locations, and at least one discovery source');
}
if (preferredLanguages.length === 0) {
  throw new Error('Campaign requires at least one language preference');
}

const sourceCounts = Object.fromEntries(sources.map((source) => [source.source_id, 0]));
const tasks = [];
let sourceCursor = 0;

const combinations = [];
for (const sector of sectors) {
  for (const location of locations) {
    for (const language of preferredLanguages) combinations.push({ sector, location, language, used: new Set() });
  }
}

// The first pass gives every combination one source, rotating through them.
// Later passes spend any remaining query budget on the sources a combination
// has not used yet, so a small campaign still reaches each enabled source.
for (let pass = 0; pass < sources.length && tasks.length < maximumQueries; pass += 1) {
  for (const combination of combinations) {
    if (tasks.length >= maximumQueries) break;
    const { sector, location, language, used } = combination;
    let selected;
    for (let offset = 0; offset < sources.length; offset += 1) {
      const candidate = sources[(sourceCursor + offset) % sources.length];
      const supportsLanguage = (candidate.supported_languages ?? []).includes(language);
      if (supportsLanguage && !used.has(candidate.source_id) && sourceCounts[candidate.source_id] < maximumPerSource) {
        selected = candidate;
        sourceCursor = (sourceCursor + offset + 1) % sources.length;
        break;
      }
    }
    if (!selected) {
      if (pass > 0) continue;
      throw new Error(`No enabled discovery source can create a ${language} query within the configured per-source limit`);
    }
    used.add(selected.source_id);
    sourceCounts[selected.source_id] += 1;
    tasks.push({
      campaign_id: campaign.campaign_id,
      query_id: `q-${String(tasks.length + 1).padStart(3, '0')}`,
      source_id: selected.source_id,
      source_type: selected.source_type,
      language,
      sector,
      location,
      keywords: campaign.keywords ?? [],
      priority: 1,
      query_limit: maximumQueries,
      maximum_candidates: campaign.maximum_candidates,
    });
  }
}

if (tasks.length === 0) {
  throw new Error('Campaign did not produce any discovery query tasks');
}

return tasks.map((json) => ({ json }));

const expected = $('Prepare Query Tasks').item.json;
const response = $json;
let value = response.json ?? response;
if (typeof value === 'string') value = JSON.parse(value.replace(/^```json\s*|```$/g, '').trim());
const requiredStrings = ['campaign_id', 'query_id', 'source_id', 'source_type', 'language', 'query', 'sector', 'location', 'intent'];
for (const field of requiredStrings) if (typeof value[field] !== 'string' || value[field].trim() === '') throw new Error(`Invalid composed query: ${field} must be a non-empty string`);
for (const field of ['campaign_id', 'query_id', 'source_id', 'source_type', 'language', 'sector', 'location']) if (value[field] !== expected[field]) throw new Error(`Invalid composed query: ${field} changed by the model`);
if (!Number.isInteger(value.priority) || value.priority < 1 || value.priority > 5) throw new Error('Invalid composed query: priority must be an integer from 1 to 5');

const frenchSector = { software: 'logiciels', 'IT services': 'services informatiques' };
const arabicSector = { software: 'البرمجيات', 'IT services': 'خدمات تكنولوجيا المعلومات' };
const sectorLabel = value.language === 'fr'
  ? (frenchSector[expected.sector] ?? expected.sector)
  : value.language === 'ar'
    ? (arabicSector[expected.sector] ?? expected.sector)
    : expected.sector;
const generatedText = `${value.query} ${value.intent}`;
const hasWebOperator = /(^|\s)(site:|inurl:|intitle:)/i.test(value.query);
const obviousEnglishInFrench = value.language === 'fr' && /\b(company|companies|company discovery|find companies|software company|software|IT services)\b/i.test(generatedText);
const hasArabicCharacters = /[\u0600-\u06FF]/.test(generatedText);
const wrongLanguage = (value.language === 'fr' && obviousEnglishInFrench) || (value.language === 'ar' && !hasArabicCharacters);
const unsuitableForSource = value.source_type !== 'web_search' && hasWebOperator;

if (wrongLanguage || unsuitableForSource) {
  if (value.language === 'fr') {
    value.query = value.source_type === 'web_search' ? `entreprises de ${sectorLabel} à ${value.location} Tunisie` : `sociétés de ${sectorLabel} à ${value.location}`;
    value.intent = `Découvrir des sociétés de ${sectorLabel} à ${value.location}`;
  } else if (value.language === 'ar') {
    value.query = `شركات ${sectorLabel} في ${value.location} تونس`;
    value.intent = `اكتشاف شركات ${sectorLabel} في ${value.location}`;
  } else {
    value.query = value.source_type === 'web_search' ? `${sectorLabel} companies in ${value.location}, Tunisia` : `${sectorLabel} companies in ${value.location}`;
    value.intent = `Discover ${sectorLabel} companies in ${value.location}`;
  }
  value._composer_fallback = true;
  value._composer_warning = `Deterministic fallback used for ${value.query_id}`;
}
return { json: value };

// n8n Code node: Run Once for All Items, after Validate Composed Query.
const warnings = [];
const queries = $input.all().map((item) => {
  const query = { ...item.json };
  if (query._composer_warning) warnings.push(query._composer_warning);
  delete query._composer_fallback;
  delete query._composer_warning;
  return query;
});
queries.sort((left, right) => left.query_id.localeCompare(right.query_id));

if (queries.length === 0) {
  throw new Error('Research plan contains no valid queries');
}

const task = $('Prepare Query Tasks').all()[0].json;
const seen = new Set();
for (const query of queries) {
  const key = [
    query.source_id,
    query.language,
    query.query.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim(),
  ].join('|');
  if (seen.has(key)) {
    throw new Error(`Duplicate query generated: ${query.query_id}`);
  }
  seen.add(key);
}

return [{
  json: {
    contract_version: '1.0',
    campaign_id: task.campaign_id,
    queries,
    stop_conditions: {
      maximum_queries: task.query_limit,
      maximum_candidates: task.maximum_candidates,
    },
    warnings,
    query_count: queries.length,
  },
}];

const form = $input.first().json;
const list = (value) => [...new Set(String(value ?? '').split(/[,;\n]+/).map(v => v.trim()).filter(Boolean))];
const name = String(form.campaign_name ?? '').trim();
const sectors = list(form.Sectors);
const governorates = list(form.Governorates);
const keywords = list(form.Keywords);
const rawLimit = form['Maximum candidates'];
const maximumCandidates = rawLimit === '' || rawLimit == null ? 200 : Number(rawLimit);
if (!name) throw new Error('Please enter a campaign name.');
if (!sectors.length) throw new Error('Please enter at least one sector.');
if (!governorates.length) throw new Error('Please enter at least one governorate.');
if (!Number.isInteger(maximumCandidates) || maximumCandidates < 1 || maximumCandidates > 200) throw new Error('Maximum candidates must be a whole number from 1 to 200.');
const languagePreferences = ['fr', 'en'];
if (sectors.length * governorates.length * languagePreferences.length > 40) throw new Error('Please use no more than 20 sector and governorate combinations because the campaign generates French and English queries.');
return [{json: {
 campaign_id: 'campaign-form-' + $execution.id,
 campaign_name: name, countries: ['TN'], governorates, cities: [], sectors, keywords,
 excluded_keywords: [], employee_range: {minimum: null, maximum: null}, maximum_candidates: maximumCandidates,
 enabled_sources: [
  {source_id:'google_maps',source_type:'maps',capabilities:['keyword','sector','location','pagination'],supported_languages:['fr','en']},
  {source_id:'b2b_tn',source_type:'directory',capabilities:['sector','location','company_lookup','pagination'],supported_languages:['fr','en']},
  {source_id:'web_search',source_type:'web_search',capabilities:['keyword','sector','location','pagination'],supported_languages:['fr','en','ar']},
  {source_id:'rne_kyc',source_type:'registry',capabilities:['company_lookup'],supported_languages:['fr']}
 ],
 official_validation:{enabled:true,source_id:'rne_kyc',mode:'WHEN_IDENTIFIER_AVAILABLE',failure_policy:'REVIEW',enrich:true},
 language_preferences:languagePreferences, limits:{maximum_queries:40,maximum_queries_per_source:16}
}}];
